# FMCSA hero background + logos -> public folder
$ErrorActionPreference = 'Stop'
$Public = 'C:\Users\Administrator\Desktop\fmsca\fmsca_frontend\public'
if (-not (Test-Path $Public)) { New-Item -ItemType Directory -Path $Public | Out-Null }
function Write-B64([string]$Name, [string]$B64) {
  $path = Join-Path $Public $Name
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($B64))
  Write-Host "OK $Name ($((Get-Item $path).Length) bytes)"
}
Write-B64 "hero-bg.jpg" @"

"@

Write-B64 "logo-cdl-brand.jpg" @"

"@

Write-B64 "logo-fmcsa-brand.jpg" @"

"@

Write-Host 'Done. Test: http://localhost:5173/hero-bg.jpg'
